test('RELEASE_CONTROL: a wrong lease_id is NOT_LEASE_HOLDER; the right one releases and the truck holds', () => {
  const h = harness({ trucks: [{ vehicle_id: 'HT-01', positionM: 100, loaded: false, socPct: 60 }] });
