  assert.equal(truth.state, 'ESTOPPED');
  assert.equal(truth.speedMps, 0);
  const ev = leaseEvents(h, 'HT-01').at(-1)!;
  assert.equal(ev.event, 'REVOKED');
  assert.equal(ev.reason, 'ESTOP');
