    assert.equal(h.command('HT-01', action).reason, 'ESTOP_ACTIVE', action);
  }
  assert.equal(h.command('HT-01', 'ESTOP').status, 'ACCEPTED');
  h.advance(200);
  assert.equal(h.latest('HT-01').state, 'ESTOPPED');
