  assert.ok(Math.abs(outside - 2.0) < 0.011, `S3 stopped ${outside} m outside ${zone.zoneId}`);
  assert.equal(stopped.m.task, null);

  // S4: deadman within ~0.6 s of the grant (live 0.4-0.6 s), lease EXPIRED ~10 s after the grant
  // (live 10.1 s), truck HOLDING afterwards.
