"""Independent read of a probe output file: every step marker, command sent, ack and lease event,
in file order, with rx_ms relative to the first record. Shares no code with the TS test."""
import json, sys

recs = [json.loads(l) for l in open(sys.argv[1])]
t0 = recs[0]['rx_ms']
for r in recs:
    k = r['kind']
    dt = (r['rx_ms'] - t0) / 1000
    if k == 'step':
        print('%7.2f ==== %s' % (dt, r['name']))
    elif k == 'sent':
        try:
            c = json.loads(r['raw'])
        except Exception:
            print('%7.2f SENT   <unparseable> %s' % (dt, r['raw']))
            continue
        if c.get('type') == 'drive':
            continue
        print('%7.2f SENT   %-26s %-6s %-16s op=%s %s' % (dt, c.get('command_id', '<none>'), c.get('vehicle_id'), c.get('action'),
                                                   c.get('operator_id'), {k2: c[k2] for k2 in ('lease_id', 'force') if k2 in c}))
    elif k == 'msg' and r['m']['type'] == 'command_ack':
        m = r['m']
        extra = {k2: m[k2] for k2 in ('reason', 'holder', 'lease_id', 'lease_idle_timeout_ms', 'deadman_ms') if k2 in m}
        print('%7.2f ACK    %-26s %-6s %-9s %s' % (dt, m['command_id'], m['vehicle_id'], m['status'], extra))
    elif k == 'msg' and r['m']['type'] in ('lease_event', 'drive_rejected'):
        m = r['m']
        print('%7.2f %-6s %s' % (dt, m['type'][:6].upper(), {k2: v for k2, v in m.items() if k2 not in ('type', 'server_time_ms')}))
    elif k in ('connected', 'closed_by_peer', 'error', 'replayed', 'done'):
        print('%7.2f %s %s' % (dt, k, {k2: v for k2, v in r.items() if k2 not in ('kind', 'rx_ms')}))

