"""Independent read of effects in a probe output file: per probed truck, every change of
(state, task, direction, speed, control) after its first command, with rx time and position."""
import json, sys

recs = [json.loads(l) for l in open(sys.argv[1])]
t0 = recs[0]['rx_ms']
hello = next(r['m'] for r in recs if r.get('m', {}).get('type') == 'hello')
start = {s['segment_id']: s['start_m'] for s in hello['route']}
first_cmd = {}
step_of = {}
step = ''
for r in recs:
    if r['kind'] == 'step': step = r['name'].split()[0]
    if r['kind'] == 'sent':
        try: c = json.loads(r['raw'])
        except Exception: continue
        v = c.get('vehicle_id')
        if c.get('type') == 'command' and v and v not in first_cmd:
            first_cmd[v] = r['rx_ms']; step_of[v] = step
for v in sorted(first_cmd, key=first_cmd.get):
    print('====', v, step_of[v])
    last = None
    for r in recs:
        m = r.get('m')
        if not m or m.get('type') != 'telemetry' or m['vehicle_id'] != v or r['rx_ms'] < first_cmd[v] - 400: continue
        c = m['control']
        k = (m['state'], m['task'], m['direction'], m['speed_mps'], m['payload_kg'], c['mode'], c['deadman'])
        if k != last:
            print('  %7.2f %-9s %-14s %s %4.1f m/s payload=%-7s pos=%8.2f (%s %6.2f) ctrl=%s' % (
                (r['rx_ms'] - t0) / 1000, m['state'], m['task'], m['direction'], m['speed_mps'], m['payload_kg'],
                start[m['segment_id']] + m['offset_m'], m['segment_id'], m['offset_m'],
                {'mode': c['mode'], 'op': c['operator_id'], 'deadman': c['deadman'], 'seq': c['last_drive_seq'], 'sent': c['last_drive_sent_ms']}))
            last = k
        if (r['rx_ms'] - first_cmd[v]) > 60000: break

