python3 - <<'EOF'
p='test/fake-probe.test.ts'
s=open(p).read()
start=s.index("// Pair every command the probe sent")
end=s.index("const outcome =")
new='''// Pair every command the probe sent with its ack, by position in the probe's file (it writes sends
// and acks under one lock, in the order it saw them). An ack belongs to the latest send of its
// command_id recorded before it. On localhost the ack can be recorded a moment before its own
// send record (the probe writes 'sent' just after the bytes leave), so when that latest send is
// already answered, the ack belongs to the next send of the id instead. No time slack: sends of
// one id can be 50 ms apart (S1), and an earlier version with a 50 ms window misattributed them.
// Milestone 1 loses no acks; with lost acks (milestone 2) this pairing must be revisited.
function pairAcks(recs: Rec[]): Send[] {
  const sends: Array<Send & { at: number }> = [];
  let step = '';
  recs.forEach((r, at) => {
    if (r.kind === 'step') step = (r.name ?? '').split(' ')[0]!;
    if (r.kind !== 'sent' || r.raw === undefined) return;
    let c: Record<string, unknown> | null = null;
    try { c = JSON.parse(r.raw) as Record<string, unknown>; } catch { c = null; }
    if (c && c.type !== 'command') return; // drive messages
    sends.push({
      at, step,
      id: c ? (typeof c.command_id === 'string' ? c.command_id : '<missing>') : '<unparseable>',
      action: c ? String(c.action) : '<unparseable>',
      vehicle: c && typeof c.vehicle_id === 'string' ? c.vehicle_id : null,
      rx: r.rx_ms,
      ack: null,
    });
  });
  recs.forEach((r, at) => {
    if (r.kind !== 'msg' || r.m?.type !== 'command_ack') return;
    const ack = r.m;
    const ofId = sends.filter((s) => s.id === ack.command_id);
    const before = ofId.filter((s) => s.at < at).at(-1);
    const target = before && !before.ack ? before : ofId.find((s) => s.at > at && !s.ack);
    if (target) target.ack = ack;
  });
  return sends;
}

'''
s=s[:start]+new+s[end:]
s=s.replace("// matches each ack to the latest send of its command_id by time, never by counting.","// matches each ack to the latest send of its command_id before it, never by counting acks.")
open(p,'w').write(s)
EOF
npx tsc --noEmit; echo "typecheck exit $?"

